(* [comment removed for export] *)
Definition fowned (em : gmap Z elt) (b : block) : Prop :=
  exists d, em !! (blk_addr b) = Some d /\ blk_size b = esize d.

(* [comment removed for export] *)
Definition SvOwn (LB : list block) (ptr len : Z) : Prop :=
  (len = 0 /\ ptr = 0) \/ (1 <= len /\ exists p, In (p, ptr, len) LB).
Definition svowned (ptr len : Z) (b : block) : Prop := 1 <= len /\ blk_addr b = ptr /\ blk_size b = len.

(* [comment removed for export] *)
Definition HdrOwn (LB : list block) (h : hdrv) : Prop :=
  SvOwn LB (hv_mp h) (hv_ml h) /\ SvOwn LB (hv_tp h) (hv_tl h) /\ 0 <= hv_ml h < 2^64 /\ 0 <= hv_tl h < 2^64.

Lemma HdrOwn_of_empty : forall LB h, hdr_empty h -> HdrOwn LB h.
Proof.
  intros LB h (E1 & E2 & E3 & E4 & _). unfold HdrOwn, SvOwn. rewrite E1, E2, E3, E4. repeat split; try lia; left; lia.
Qed.

