Definition dl_seg1_post (ra sp gp tp s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (t0 t1 t2 t3 t4 t5 t6 s0 : word) (Fa first lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists m' junk,
    ms' = MS (mkR ra (wz (bv_unsigned sp + -32)) gp tp t0 t1 t2 (wz (Fa + 32)) s1 (wz first) (wz Fa) a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (wz (if first =? Fa + 32 then DL_EXIT else DL_LOOP)) fc None m' (seg_rom usegs)
    /\ munch [(bv_unsigned sp + -32, bv_unsigned sp)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp + -32)
    /\ rw_cells usegs m' (bv_unsigned sp + -32) [CB 8 junk; C8 s1; C8 s0; C8 ra].
