(* [comment removed for export] *)
Lemma dl_exit : forall (rax s0x s1x gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (rav s0v s1v : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) (SP lo : Z) (junk : list byte),
  rw_cells usegs m (SP + -32) [CB 8 junk; C8 s1v; C8 s0v; C8 rav] ->
  stk usegs m lo (SP + -32) -> 0 <= lo -> lo + 32 <= SP -> SP <= 2^64 -> mem_inv usegs m ->
  evt usegs (fun ms' => ms' = MS (mkR rav (wz SP) gp tp t0 t1 t2 s0v s1v a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                            F (ret_pc rav) fc None m (seg_rom usegs)
                      /\ stk usegs m lo SP)
    (MS (mkR rax (wz (SP + -32)) gp tp t0 t1 t2 s0x s1x a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
