(* [comment removed for export] *)
Definition dl_rem (m : mem) (LBc : list block) (hL : Z) (bs : list block) (em : gmap Z elt) : Prop :=
  forall A b B, bs = A ++ b :: B ->
    In b LBc /\ exists d (wprev : word), em !! (blk_addr b) = Some d /\ blk_size b = esize d
      /\ rw_cells usegs m (blk_addr b) [C8 (wz (lhead hL (map blk_addr B))); C8 wprev]
      /\ rw_cells usegs m (blk_addr b + 48) (ValCells d).

Section W.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.

  (* [comment removed for export] *)
  Definition dlI_post (sp gp s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (LBc : list block) (hL lo B : Z) (b : block) (R : list block) (em : gmap Z elt) (errv : word)
      (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (s' : PState),
      let nxt := lhead hL (map blk_addr R) in
      let LB1 := hs_lb_remove H (blk_id b) LBc in
      cfg_ms c = MS (mkR (wz DL_RA) (wz (bv_unsigned sp + -32)) gp (wz RATP) t0 t1 t2 (wz hL) (wz nxt) (wz nxt) a1 a2 a3 a4 a5 a6 a7
                       s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (wz (if nxt =? hL then DL_EXIT else DL_LOOP)) fc None m' (seg_rom usegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv usegs m' /\ stk usegs m' lo (bv_unsigned sp + -32)
      /\ rw_cells usegs m' RERRNO [C4 errv] /\ hs_rauxv_ok H m' B
      /\ hs_RHEAP H s' LB1 m'
      /\ rheap_pres LB1 (bv_unsigned sp + -32) m m'
      /\ dl_rem m' LB1 hL R em.
Scheme kc__5 := Elimination for Corelib.Init.Datatypes.prod Sort Prop.
Scheme kc__6 := Elimination for LinuxProcessSemantics.LinuxProcessSem.Run.config Sort Prop.
Scheme kc__7 := Elimination for Corelib.Init.Datatypes.list Sort Prop.

  Lemma dl_iter : forall (rax s1x sp gp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
      (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model) (s : PState) (LBc : list block) (hL lo B : Z)
      (b : block) (R : list block) (em : gmap Z elt) (errv : word),
    dl_rem m LBc hL (b :: R) em -> List.NoDup (map blk_id (b :: R)) -> em_ok em ->
    hceil <= hL -> hL + 16 <= 2^64 ->
    hs_RHEAP H s LBc m -> hs_KREL H s mo ->
    hs_rauxv_ok H m B -> bv_unsigned sp <= B ->
    stk usegs m lo (bv_unsigned sp + -32) -> hceil <= lo -> lo <= bv_unsigned sp - DELETE_LIST_STACK ->
    rw_cells usegs m RERRNO [C4 errv] -> mem_inv usegs m ->
    hs_SR H (dlI_post sp gp s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LBc hL lo B b R em errv m mo)
      (mkCfg (MS (mkR rax (wz (bv_unsigned sp + -32)) gp (wz RATP) t0 t1 t2 (wz hL) s1x (wz (blk_addr b)) a1 a2 a3 a4 a5 a6 a7
                       s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
