  (* [comment removed for export] *)
  Definition dl_loop_post (sp gp s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (LBc : list block) (hL lo B : Z) (bs : list block) (errv : word) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists s1x t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (s' : PState) (LB' : list block),
      cfg_ms c = MS (mkR (wz DL_RA) (wz (bv_unsigned sp + -32)) gp (wz RATP) t0 t1 t2 (wz hL) s1x a0 a1 a2 a3 a4 a5 a6 a7
                       s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (wz DL_EXIT) fc None m' (seg_rom usegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv usegs m' /\ stk usegs m' lo (bv_unsigned sp + -32)
      /\ rw_cells usegs m' RERRNO [C4 errv] /\ hs_rauxv_ok H m' B
      /\ hs_RHEAP H s' LB' m'
      /\ (forall b', In b' LB' <-> (In b' LBc /\ ~ In (blk_id b') (map blk_id bs)))
      /\ lb_bytes LB' + lb_bytes bs = lb_bytes LBc /\ (length LB' + length bs = length LBc)%nat
      /\ xpres LB' (bv_unsigned sp + -32) [] m m'.

  Lemma dl_loop : forall (R : list block) (b : block)
      (rax s1x sp gp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
      (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model) (s : PState) (LBc : list block) (hL lo B : Z)
      (em : gmap Z elt) (errv : word),
    dl_rem m LBc hL (b :: R) em -> List.NoDup (map blk_id (b :: R)) -> em_ok em ->
    hceil <= hL -> hL + 16 <= 2^64 ->
    hs_RHEAP H s LBc m -> hs_KREL H s mo ->
    hs_rauxv_ok H m B -> bv_unsigned sp <= B ->
    stk usegs m lo (bv_unsigned sp + -32) -> hceil <= lo -> lo <= bv_unsigned sp - DELETE_LIST_STACK ->
    rw_cells usegs m RERRNO [C4 errv] -> mem_inv usegs m ->
    hs_SR H (dl_loop_post sp gp s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LBc hL lo B (b :: R) errv m mo)
      (mkCfg (MS (mkR rax (wz (bv_unsigned sp + -32)) gp (wz RATP) t0 t1 t2 (wz hL) s1x (wz (blk_addr b)) a1 a2 a3 a4 a5 a6 a7
                       s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                 F (wz DL_LOOP) fc None m (seg_rom usegs)) mo).
