Section W.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.

  Definition rsfree_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (D ptr len lo B : Z) (errv : word) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (s' : PState) (LB' : list block),
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom usegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv usegs m' /\ stk usegs m' lo (bv_unsigned sp)
      /\ rw_cells usegs m' (errno_addr tp) [C4 errv] /\ hs_rauxv_ok H m' B
      /\ hs_RHEAP H s' LB' m'
      /\ (forall b, In b LB' <-> (In b LB /\ ~ svowned ptr len b))
      /\ lb_bytes LB' <= lb_bytes LB /\ (length LB' <= length LB)%nat
      /\ rw_cells usegs m' D [C8 (wz 0); C8 (wz 0)]
      /\ xpres LB' (bv_unsigned sp) [(D, D + 16)]%Z m m'.

  Definition rsfree_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (D ptr len lo B : Z) (errv : word),
      a1 = wz D -> a2 = wz 0 -> a3 = wz 0 ->
      rw_cells usegs m D [C8 (wz ptr); C8 (wz len)] -> SvOwn LB ptr len -> 0 <= len < 2^64 ->
      bv_unsigned sp <= D -> D + 16 <= B ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B ->
      stk usegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - RSFREE_STACK ->
      rw_cells usegs m (errno_addr tp) [C4 errv] -> mem_inv usegs m -> tp = wz RATP ->
      hs_SR H (rsfree_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB D ptr len lo B errv m mo)
        (mkCfg (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (wz P_REALLOC_STRING) fc None m (seg_rom usegs)) mo).

  Lemma rsfree_spec : rsfree_stmt.
