(* [comment removed for export] *)
Definition HdrDisj (em : gmap Z elt) (h : hdrv) : Prop :=
  (1 <= hv_ml h -> em !! (hv_mp h) = None) /\ (1 <= hv_tl h -> em !! (hv_tp h) = None)
  /\ (1 <= hv_ml h -> 1 <= hv_tl h -> hv_mp h <> hv_tp h).

Lemma HdrDisj_of_empty : forall em h, hdr_empty h -> HdrDisj em h.
Proof. intros em h (E1 & E2 & E3 & E4 & _). unfold HdrDisj. rewrite E2, E4. repeat split; intros; lia. Qed.

(* [comment removed for export] *)
Definition hdr_cleared (h : hdrv) : hdrv := mkHV 0 0 0 0 (hv_ver h) (hv_vb h).

(* [comment removed for export] *)
Definition bfowned (em : gmap Z elt) (h : hdrv) (b : block) : Prop :=
  fowned em b \/ svowned (hv_mp h) (hv_ml h) b \/ svowned (hv_tp h) (hv_tl h) b.

(* [comment removed for export] *)
Lemma bf_seg1 : forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (Fa lo : Z),
  a0 = wz Fa ->
  stk usegs m lo (bv_unsigned sp) -> lo + 16 <= bv_unsigned sp -> hceil <= lo ->
  mem_inv usegs m ->
  evt usegs (fun ms' => exists m',
      ms' = MS (mkR (wz BF_RA1) (wz (bv_unsigned sp + -16)) gp tp t0 t1 t2 (wz Fa) s1 (wz Fa) a1 a2 a3 a4 a5 a6 a7
                    s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (wz P_DELETE_LIST) fc None m' (seg_rom usegs)
      /\ munch [(bv_unsigned sp + -16, bv_unsigned sp)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
      /\ stk usegs m' lo (bv_unsigned sp + -16)
      /\ rw_cells usegs m' (bv_unsigned sp + -16) [C8 s0; C8 ra])
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
