Section W.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.

  Definition bfields_dtor_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (Fa lo B : Z) (em : gmap Z elt) (h : hdrv) (errv : word) (m : mem) (mo : Model)
      : config -> Prop :=
    fun c => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (s' : PState) (LB' : list block),
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom usegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv usegs m' /\ stk usegs m' lo (bv_unsigned sp)
      /\ rw_cells usegs m' (errno_addr tp) [C4 errv] /\ hs_rauxv_ok H m' B
      /\ hs_RHEAP H s' LB' m'
      /\ (forall b, In b LB' <-> (In b LB /\ ~ bfowned em h b))
      /\ lb_bytes LB' <= lb_bytes LB /\ (length LB' <= length LB)%nat
      /\ rw_cells usegs m' (Fa + 48) (HdrCells (hdr_cleared h))
      /\ xpres LB' (bv_unsigned sp) [(Fa + 48, Fa + 80)]%Z m m'.

  Definition bfields_dtor_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (Fa lo B : Z) (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt) (h : hdrv) (errv : word),
      a0 = wz Fa ->
      FieldsC m Fa S L ns ls em -> FieldsOwn LB em ->
      rw_cells usegs m (Fa + 48) (HdrCells h) -> HdrOwn LB h -> HdrDisj em h ->
      bv_unsigned sp <= Fa -> Fa + 80 <= B ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B ->
      stk usegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - BFIELDS_DTOR_STACK ->
      rw_cells usegs m (errno_addr tp) [C4 errv] -> mem_inv usegs m -> tp = wz RATP ->
      hs_SR H (bfields_dtor_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB Fa lo B em h errv m mo)
        (mkCfg (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (wz P_BFIELDS_DTOR) fc None m (seg_rom usegs)) mo).

  Lemma bfields_dtor_spec : bfields_dtor_stmt.
  Proof.
    intros until errv. intros -> FC OWN HDR HOWN HDJ SF FB HP KREL AUX SPB ST CEIL LO ERR MI TP.
    unfold BFIELDS_DTOR_STACK, RFREE_STACK in LO. pose proof CEIL as CEIL'. hcb. unfold wz in *. subst tp.
    assert (EA : errno_addr (Z_to_bv 64 RATP) = RERRNO) by (unfold RATP, RERRNO; rewrite unsigned_lit; lia).
    rewrite EA in ERR. sp_range sp.
    pose proof (rw_cells_bound _ _ _ _ HDR) as HB. unfold HdrCells in HB. cbn [cells_size csize Nat.add length] in HB.
    pose proof FC as (_ & _ & _ & _ & _ & _ & _ & LE & EOK & HFa & _).
    pose proof HOWN as (OM & OT & RM & RT). pose proof HDJ as (JM & JT & JMT).
    pose proof (blocks_below_hceil H HH _ _ _ HP) as HBK.
    (* [comment removed for export] *)
    eapply (hh_evt_then H HH); [exact KREL| eapply bf_seg1; try eassumption; try reflexivity; lia|].
    intros ms1 (m1 & -> & MU & WM & MI1 & ST1 & FR1). unfold wz.
    eapply (rw_cells_transport usegs _ m m1) in ERR; [| exact MU| exact WM| unfold RERRNO in *; cbn; lia].
    eapply (rw_cells_transport usegs _ m m1) in HDR; [| exact MU| exact WM| cbn; lia].
    assert (HP1 : hs_RHEAP H s LB m1).
    { eapply (hh_RHEAP_frame H HH); [exact HP| exact MU| exact WM|]. constructor; [left; cbn; lia| constructor]. }
    assert (AUX1 : hs_rauxv_ok H m1 B).
    { eapply (hh_rauxv_frame H HH); [exact AUX| exact MU| exact WM|]. unfold RAUXV_CELL in *. constructor; [cbn; lia| constructor]. }
    assert (FC1 : FieldsC m1 Fa S L ns ls em).
